from rdkit import Chem
m=Chem.MolFromMolFile('answer.mol',removeHs=False)
orig=Chem.MolFromMolFile('drawing_assigned.mol',removeHs=False)
orig=Chem.AddHs(orig)
for a in orig.GetAtoms():
 if a.HasProp('_CIPCode'):print('orig',a.GetIdx(),a.GetChiralTag(),a.GetProp('_CIPCode'),[n.GetIdx() for n in a.GetNeighbors()])
for a in m.GetAtoms():
 if a.HasProp('_CIPCode'):print('m',a.GetIdx(),a.GetChiralTag(),a.GetProp('_CIPCode'),[n.GetIdx() for n in a.GetNeighbors()])
Chem.AssignStereochemistryFrom3D(m,replaceExistingTags=True)
Chem.AssignStereochemistry(m,cleanIt=True,force=True)
for a in m.GetAtoms():
 if a.HasProp('_CIPCode'):print('3d',a.GetIdx(),a.GetChiralTag(),a.GetProp('_CIPCode'))
print('orig smiles',Chem.MolToSmiles(Chem.RemoveHs(orig)))
print('m smiles',Chem.MolToSmiles(Chem.RemoveHs(m)))
